const body = $json.body || $json;
const now = new Date();
const saturday = new Date(now); saturday.setDate(now.getDate() + ((6 - now.getDay() + 7) % 7 || 7)); saturday.setHours(10,0,0,0);
const sunday = new Date(now); sunday.setDate(now.getDate() + ((0 - now.getDay() + 7) % 7 || 7)); sunday.setHours(14,0,0,0);
return [{ json: { ...body, suggested_slots: [saturday.toISOString(), sunday.toISOString()] } }];

const slot = $json.selected_slot || $json.suggested_slots[0];
const start = new Date(slot);
const end = new Date(start.getTime() + 60 * 60 * 1000);
return [{ json: { ...$json, appointment: { start_time: start.toISOString(), end_time: end.toISOString(), status: 'confirmed' } } }];
